theorem sq_quot_aux {G : Type*} [CommGroup G] (u : G) (n : ℤ) :
    ∃ c : Bool, (QuotientGroup.mk (s := Subgroup.square G) (u ^ n)) =
      QuotientGroup.mk (s := Subgroup.square G) (u ^ (c.toNat)) := by
  rcases Int.emod_two_eq_zero_or_one n with h | h
  · refine ⟨false, ?_⟩
    rw [QuotientGroup.eq]
    refine ⟨u ^ (-(n / 2)), ?_⟩
    simp only [Bool.toNat_false, pow_zero, mul_one]
    rw [← zpow_add, ← zpow_neg]
    congr 1
    omega
  · refine ⟨true, ?_⟩
    rw [QuotientGroup.eq]
    refine ⟨u ^ (-(n / 2)), ?_⟩
    simp only [Bool.toNat_true, pow_one]
    have : (u ^ n)⁻¹ * u = u ^ (-n + 1) := by rw [zpow_add, zpow_neg, zpow_one]
    rw [this, ← zpow_add]
    congr 1
    omega

open NumberField in
theorem units_sq_index_le (F : Type) [Field F] [NumberField F] :
    Finite ((𝓞 F)ˣ ⧸ Subgroup.square ((𝓞 F)ˣ)) ∧
    (Subgroup.square ((𝓞 F)ˣ)).index ≤ 2 ^ Module.finrank ℚ F := by
  classical
  haveI : IsCyclic (Units.torsion F) := isCyclic_subgroup_units _
  obtain ⟨ζ, hζ⟩ := IsCyclic.exists_generator (α := Units.torsion F)
  have hsurj : Function.Surjective (fun p : Bool × (Fin (Units.rank F) → Bool) =>
      (QuotientGroup.mk (s := Subgroup.square ((𝓞 F)ˣ))
        (((ζ : (𝓞 F)ˣ)) ^ p.1.toNat * ∏ i, (Units.fundSystem F i) ^ (p.2 i).toNat))) := by
    intro q
    obtain ⟨x, rfl⟩ := QuotientGroup.mk_surjective q
    obtain ⟨⟨t, e⟩, hx, -⟩ := Units.exist_unique_eq_mul_prod F x
    obtain ⟨k, hk⟩ := Subgroup.mem_zpowers_iff.mp (hζ t)
    have hk' : ((ζ : (𝓞 F)ˣ)) ^ k = (t : (𝓞 F)ˣ) := by
      rw [← hk]; simp
    obtain ⟨c0, hc0⟩ := sq_quot_aux (ζ : (𝓞 F)ˣ) k
    choose c hc using fun i => sq_quot_aux (Units.fundSystem F i) (e i)
    refine ⟨(c0, c), ?_⟩
    show QuotientGroup.mk _ = _
    rw [hx, ← hk']
    rw [QuotientGroup.mk_mul, QuotientGroup.mk_mul, QuotientGroup.mk_prod, QuotientGroup.mk_prod, hc0]
    congr 1
    exact Finset.prod_congr rfl fun i _ => (hc i).symm
  refine ⟨Finite.of_surjective _ hsurj, ?_⟩
  have h1 := Nat.card_le_card_of_surjective _ hsurj
  have h2 : Nat.card (Bool × (Fin (Units.rank F) → Bool)) = 2 * 2 ^ Units.rank F := by
    simp [Nat.card_prod, Nat.card_eq_fintype_card]
  have h3 : Units.rank F + 1 ≤ Module.finrank ℚ F := by
    have := InfinitePlace.card_add_two_mul_card_eq_rank F
    have h4 : Fintype.card (InfinitePlace F) = InfinitePlace.nrRealPlaces F + InfinitePlace.nrComplexPlaces F :=
      InfinitePlace.card_eq_nrRealPlaces_add_nrComplexPlaces F
    have h5 : Units.rank F = Fintype.card (InfinitePlace F) - 1 := rfl
    have : 0 < Fintype.card (InfinitePlace F) := Fintype.card_pos
    omega
  rw [Subgroup.index]
  calc _ ≤ _ := h1
    _ = 2 ^ (Units.rank F + 1) := by rw [h2, pow_succ]; ring
    _ ≤ _ := Nat.pow_le_pow_right (by norm_num) h3

